*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #eaeaea;
  --green: #2ecc71;
  --red: #e74c3c;
  --yellow: #f1c40f;
  --blue: #3498db;
  --pad-off-opacity: 0.35;
  --pad-glow: 0 0 24px 4px currentColor;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-container {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--text);
}

.status-bar {
  display: flex;
  justify-content: space-between;
  width: 100%;
  font-size: 1.1rem;
  font-weight: 600;
  gap: 12px;
}

#levelDisplay { color: var(--yellow); }
#statusMessage { color: var(--blue); }

.board {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 360px;
}

.pad {
  border: none;
  border-radius: 16px;
  cursor: pointer;
  opacity: var(--pad-off-opacity);
  transition: opacity 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
  position: relative;
  min-height: 80px;
}

.pad:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
  opacity: 0.8;
}

.pad:hover {
  opacity: 0.6;
}

.pad:active,
.pad.active {
  opacity: 1;
  box-shadow: var(--pad-glow);
  transform: scale(0.96);
}

.pad-green { background: var(--green); color: var(--green); }
.pad-red { background: var(--red); color: var(--red); }
.pad-yellow { background: var(--yellow); color: var(--yellow); }
.pad-blue { background: var(--blue); color: var(--blue); }

.controls {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 12px 32px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  background: var(--blue);
  color: #fff;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.btn:hover { background: #2980b9; }
.btn:focus-visible { outline: 3px solid var(--yellow); outline-offset: 3px; }
.btn:active { transform: scale(0.95); }
.btn[hidden] { display: none; }

@media (max-width: 400px) {
  .game-container { padding: 24px 16px; gap: 16px; }
  h1 { font-size: 1.4rem; }
  .status-bar { font-size: 1rem; }
  .board { gap: 8px; }
  .btn { padding: 10px 24px; font-size: 1rem; }
}

(function () {
  'use strict';

  const pads = Array.from(document.querySelectorAll('.pad'));
  const levelDisplay = document.getElementById('levelDisplay');
  const statusMessage = document.getElementById('statusMessage');
  const startBtn = document.getElementById('startBtn');
  const restartBtn = document.getElementById('restartBtn');

  const COLORS = ['green', 'red', 'yellow', 'blue'];
  const FLASH_ON = 400;
  const FLASH_OFF = 200;

  let sequence = [];
  let playerIndex = 0;
  let level = 0;
  let acceptingInput = false;
  let playingSequence = false;
  let gameActive = false;

  function randomPad() {
    return Math.floor(Math.random() * 4);
  }

  function setStatus(msg) {
    statusMessage.textContent = msg;
  }

  function updateLevel() {
    levelDisplay.textContent = 'Level: ' + level;
  }

  function flashPad(index, duration) {
    return new Promise((resolve) => {
      const pad = pads[index];
      pad.classList.add('active');
      setTimeout(() => {
        pad.classList.remove('active');
        setTimeout(resolve, FLASH_OFF);
      }, duration || FLASH_ON);
    });
  }

  async function playSequence() {
    playingSequence = true;
    acceptingInput = false;
    setStatus('Watch...');
    for (const idx of sequence) {
      await flashPad(idx);
    }
    playingSequence = false;
    acceptingInput = true;
    setStatus('Your turn');
  }

  function nextRound() {
    level++;
    updateLevel();
    playerIndex = 0;
    sequence.push(randomPad());
    playSequence();
  }

  function startGame() {
    sequence = [];
    level = 0;
    playerIndex = 0;
    gameActive = true;
    acceptingInput = false;
    playingSequence = false;
    startBtn.hidden = true;
    restartBtn.hidden = true;
    updateLevel();
    nextRound();
  }

  function gameOver() {
    gameActive = false;
    acceptingInput = false;
    playingSequence = false;
    setStatus('Game over');
    restartBtn.hidden = false;
    startBtn.hidden = true;
  }

  function handlePadClick(index) {
    if (!gameActive || !acceptingInput || playingSequence) return;
    flashPad(index, 200);
    if (sequence[playerIndex] === index) {
      playerIndex++;
      if (playerIndex === sequence.length) {
        acceptingInput = false;
        setStatus('Nice!');
        setTimeout(nextRound, 800);
      }
    } else {
      gameOver();
    }
  }

  pads.forEach((pad) => {
    pad.addEventListener('click', () => {
      const idx = parseInt(pad.dataset.pad, 10);
      handlePadClick(idx);
    });
  });

  startBtn.addEventListener('click', startGame);
  restartBtn.addEventListener('click', startGame);

  updateLevel();
})();
